	router.POST(baseURL+"/files", wrapper.UploadFile)
	router.GET(baseURL+"/files/:file_id", wrapper.DownloadFile)
	router.POST(baseURL+"/invitations/:invitation_id/decision", wrapper.DecideInvitation)
	router.GET(baseURL+"/matches/:match_id", wrapper.GetMatch)
	router.GET(baseURL+"/matches/:match_id/dispute", wrapper.GetDispute)
	router.POST(baseURL+"/matches/:match_id/dispute/resolve", wrapper.ResolveDispute)
