	router.DELETE(baseURL+"/teams/:team_id", wrapper.DeleteTeam)
	router.GET(baseURL+"/teams/:team_id", wrapper.GetTeam)
	router.PATCH(baseURL+"/teams/:team_id", wrapper.UpdateTeam)
	router.PUT(baseURL+"/teams/:team_id/captain", wrapper.TransferCaptain)
	router.POST(baseURL+"/teams/:team_id/invitations", wrapper.CreateInvitation)
	router.DELETE(baseURL+"/teams/:team_id/invitations/:invitation_id", wrapper.RevokeInvitation)
	router.GET(baseURL+"/teams/:team_id/members", wrapper.ListTeamMembers)
	router.DELETE(baseURL+"/teams/:team_id/members/:user_id", wrapper.RemoveTeamMember)
	router.GET(baseURL+"/teams/:team_id/rating-history", wrapper.ListRatingHistory)
	router.GET(baseURL+"/tournaments", wrapper.ListTournaments)
	router.POST(baseURL+"/tournaments", wrapper.CreateTournament)
	router.GET(baseURL+"/tournaments/:tournament_id", wrapper.GetTournament)
	router.PATCH(baseURL+"/tournaments/:tournament_id", wrapper.UpdateTournament)
	router.GET(baseURL+"/tournaments/:tournament_id/applications", wrapper.ListApplications)
	router.POST(baseURL+"/tournaments/:tournament_id/applications", wrapper.SubmitApplication)
	router.POST(baseURL+"/tournaments/:tournament_id/applications/:application_id/review", wrapper.ReviewApplication)
	router.POST(baseURL+"/tournaments/:tournament_id/applications/:application_id/withdraw", wrapper.WithdrawApplication)
	router.GET(baseURL+"/tournaments/:tournament_id/bracket", wrapper.GetBracket)
	router.POST(baseURL+"/tournaments/:tournament_id/cancel", wrapper.CancelTournament)
	router.POST(baseURL+"/tournaments/:tournament_id/complete", wrapper.CompleteTournament)
	router.PUT(baseURL+"/tournaments/:tournament_id/draw", wrapper.ConfirmDraw)
	router.POST(baseURL+"/tournaments/:tournament_id/draw-previews", wrapper.PreviewDraw)
	router.GET(baseURL+"/tournaments/:tournament_id/events", wrapper.StreamTournamentEvents)
	router.GET(baseURL+"/tournaments/:tournament_id/export", wrapper.ExportTournament)
	router.GET(baseURL+"/tournaments/:tournament_id/matches", wrapper.ListMatches)
